// Imports competitive decklists (official "Top Decks" / "Best-Of" articles, saved as text in data/decklists/)
// into data/decks.json: one deck per Legend, the best-placed list first. Cards banned since the list was played
// are replaced by the same player's sideboard cards (the deck is then marked "adapté post-ban").
// Decks generated by seed-legend-decks.js are removed for the Legends covered here.
// Usage: node import-decklists.js   (sources listed in SOURCES, most recent first)
const fs = require('fs');
const cards = require('./data/cards.json');

const SOURCES = [
  { file: 'data/decklists/rc-europe-2026-11.txt', label: 'RC Europe, nov. 2026' },
  { file: 'data/decklists/rq-los-angeles-2026-09.txt', label: 'RQ Los Angeles, sept. 2026' },
];
// Standard ban list (Radiance update effective November 23, 2026, plus earlier bans)
const BANNED = ['Riven, Broken Blade', "Zhonya's Hourglass", 'Stellacorn Herder', 'Nocturne, Horrifying', 'Rhasa the Sunderer',
  'Brynhir Thundersong', 'Dazzling Aurora', 'Baited Hook', "Emperor's Dais", 'Star Spring', 'Stacked Deck', "Reaver's Row"];

const norm = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’‘]/g, "'").toLowerCase().replace(/[^a-z0-9']+/g, ' ').trim();
const byName = {};
for (const c of cards) { const n = norm(c.name); if (!byName[n] || (byName[n].alt && !c.alt) || (byName[n].supertype === 'Token' && c.supertype !== 'Token')) byName[n] = c; }
// names used in the articles that differ from the card data
const ALIAS = { 'kennen, heart of the tempest': 'Yordle, Heart of the Tempest', 'trapping ground': 'Trapping Grounds' };
const card = name => byName[norm(ALIAS[name.toLowerCase()] || name)] || byName[norm(name.replace(',', ' -'))];
const banned = new Set(BANNED.map(norm));
const isBanned = name => banned.has(norm(name));
const SEC = { 'legend': 'legend', 'champion': 'champion', 'main deck': 'main', 'battlefields': 'battlefields', 'rune pool': 'runes', 'runes': 'runes', 'sideboard': 'side' };

function parse(text) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const out = [];
  let d = null, sec = null;
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i], h = /^([A-Za-z ]+):$/.exec(l);
    if (h && SEC[h[1].toLowerCase()]) {
      sec = SEC[h[1].toLowerCase()];
      if (sec === 'legend') {
        // the player's name is the line before "Legend Rank" / "Overall Ranking"
        let k = i - 1; while (k > 0 && /^(Legend Rank|Overall Ranking)/.test(lines[k])) k--;
        d = { player: lines[k], legend: [], champion: [], main: [], battlefields: [], runes: [], side: [] };
        out.push(d);
      }
      continue;
    }
    const m = /^(\d+)\s+(.+)$/.exec(l);
    if (d && sec && m) d[sec].push({ n: +m[1], name: m[2].trim() });
    else if (d && sec === 'side' && !m) sec = null; // end of the list
  }
  return out;
}

const missing = [], decks = [];
for (const src of SOURCES) {
  if (!fs.existsSync(src.file)) continue;
  for (const raw of parse(fs.readFileSync(src.file, 'utf8'))) {
    const L = raw.legend[0] && card(raw.legend[0].name);
    if (!L) { missing.push(`${src.label} / ${raw.player}: légende ${raw.legend[0] && raw.legend[0].name}`); continue; }
    if (decks.some(x => x.legend === L.name)) continue; // one list per Legend: the first (best placed / most recent)
    const notes = [];
    const ok = list => list.filter(x => { if (!card(x.name)) { missing.push(`${src.label} / ${raw.player}: ${x.name}`); return false; } return true; });
    let main = ok(raw.main), side = ok(raw.side).filter(x => !isBanned(x.name)), champ = ok(raw.champion), bfs = ok(raw.battlefields);
    // banned main deck cards -> the player's own sideboard, then extra copies of the deck's cards
    let lost = 0;
    main = main.filter(x => { if (isBanned(x.name)) { lost += x.n; notes.push(x.name); return false; } return true; });
    const addCopies = (name, n) => { const e = main.find(x => norm(x.name) === norm(name)); const have = e ? e.n : 0, k = Math.min(n, 3 - have); if (k <= 0) return 0; if (e) e.n += k; else main.push({ name, n: k }); return k; };
    for (const x of side) { if (!lost) break; lost -= addCopies(x.name, Math.min(x.n, lost)); }
    for (const x of main.slice()) { if (!lost) break; lost -= addCopies(x.name, lost); }
    // banned chosen champion -> another champion of the Legend found in the list, else any legal one
    if (champ[0] && isBanned(champ[0].name)) {
      notes.push(champ[0].name);
      const tag = (L.tags || [])[0];
      const alt = main.find(x => card(x.name).supertype === 'Champion' && (card(x.name).tags || []).includes(tag))
        || { name: (cards.find(c => c.supertype === 'Champion' && c.type === 'Unit' && (c.tags || []).includes(tag) && !isBanned(c.name)) || {}).name };
      if (!alt.name) { missing.push(`${src.label} / ${raw.player}: aucun champion légal`); continue; }
      const e = main.find(x => x.name === alt.name); if (e) { e.n--; if (!e.n) main.splice(main.indexOf(e), 1); addCopies(side[0] ? side[0].name : main[0].name, 1); }
      champ = [{ n: 1, name: alt.name }];
    }
    bfs = bfs.filter(x => { if (isBanned(x.name)) { notes.push(x.name); return false; } return true; });
    decks.push({ legend: L.name, player: raw.player, src: src.label, notes, cards: { legend: [{ n: 1, name: L.name }], champion: champ, main, battlefields: bfs, runes: ok(raw.runes), side } });
  }
}
// battlefields lost to the ban: the most played legal battlefields of the other lists
const bfCount = {};
for (const d of decks) for (const b of d.cards.battlefields) bfCount[b.name] = (bfCount[b.name] || 0) + 1;
const popular = Object.keys(bfCount).sort((a, b) => bfCount[b] - bfCount[a]);
for (const d of decks) for (const b of popular) { if (d.cards.battlefields.length >= 3) break; if (!d.cards.battlefields.some(x => x.name === b)) d.cards.battlefields.push({ n: 1, name: b }); }

const FILE = 'data/decks.json';
const old = JSON.parse(fs.readFileSync(FILE, 'utf8'));
const legendOf = d => (cards.find(c => c.id === d.cards.legend[0].id) || {}).name;
const covered = new Set(decks.map(d => d.legend));
const kept = old.filter(d => !d.competitive && !(d.generated && covered.has(legendOf(d))));
const out = decks.map(d => {
  const total = d.cards.main.reduce((a, x) => a + x.n, 0) + 1;
  if (total !== 40) console.log(`⚠ ${d.legend} (${d.player}) : ${total} cartes avec le champion`);
  const ids = list => list.map(x => ({ id: card(x.name).id, n: x.n }));
  return {
    id: 'comp-' + norm(d.legend).replace(/[^a-z0-9]+/g, '-'), competitive: true,
    name: `${d.legend.split(',')[0]} — ${d.player} (${d.src}${d.notes.length ? ', adapté post-ban' : ''})`,
    source: d.src, player: d.player, legendName: d.legend, banReplaced: d.notes,
    cards: { legend: ids(d.cards.legend), champion: ids(d.cards.champion), main: ids(d.cards.main), battlefields: ids(d.cards.battlefields), runes: ids(d.cards.runes), side: ids(d.cards.side) },
  };
});
fs.writeFileSync(FILE, JSON.stringify([...old.filter(d => d.starter), ...out, ...kept.filter(d => !d.starter)], null, 1));
if (missing.length) console.log('Introuvables :\n  ' + [...new Set(missing)].join('\n  '));
console.log(`${out.length} decks compétitifs (${out.filter(d => d.banReplaced.length).length} adaptés post-ban), ${kept.filter(d => d.generated).length} decks générés gardés pour les autres légendes.`);
for (const d of out.filter(d => d.banReplaced.length)) console.log(`  ${d.legendName} : retiré ${d.banReplaced.join(', ')}`);
